import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%82%A8%E3%83%87%E3%82%A3%E3%82%BF%E8%AA%BF%E6%9F%BB.html","title":"エディタ調査","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":9.27,"words":2781},"filePathRelative":"エディタ調査.md"}`),a={name:`エディタ調査.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="エディタ調査" tabindex="-1"><a class="header-anchor" href="#エディタ調査"><span>エディタ調査</span></a></h1><p><a href="./Rhinocs.html">Rhinocs</a>を作るにあたり、他のエディタの挙動を調べた時のメモ。</p><ul><li><a href="https://github.com/xyzzy-022/xyzzy" target="_blank" rel="noopener noreferrer">xyzzy-022/xyzzy: xyzzy 0.2.2 系列。有志により開発が継続中です。</a> 昔結構読んだコードなのでxyzzyを参考にする事多し</li><li><a href="https://web.sfc.wide.ad.jp/~sagawa/gnujdoc/elisp-manual-20-2.5/index.html#SEC_Top" target="_blank" rel="noopener noreferrer">GNU Emacs Lispリファレンスマニュアル: GNU Emacs Lispリファレンスマニュアル</a> emacs lispのwindowとかbufferとかは良く見る</li><li><a href="https://github.com/lem-project/lem/tree/main" target="_blank" rel="noopener noreferrer">lem-project/lem: General-purpose editor/IDE with high expansibility in Common Lisp</a> lemもたまに参考にする</li></ul><p>なお、新しいのは上に足していきます。</p><h2 id="モード行の調査" tabindex="-1"><a class="header-anchor" href="#モード行の調査"><span>モード行の調査</span></a></h2><p>モード行を実装したいので調査。</p><p>まずはemacs lispのマニュアルを読む。</p><p><a href="https://web.sfc.wide.ad.jp/~sagawa/gnujdoc/elisp-manual-20-2.5/elisp-ja_23.html#SEC350" target="_blank" rel="noopener noreferrer">GNU Emacs Lispリファレンスマニュアル: Modes</a></p><p>mode-line-formatはリストか。</p><p>xyzzyは文字列に％で変数が指定出来る何かだった気がするな。</p><p><a href="http://hie.s64.xrea.com/xyzzy/reference/html/window.html#mode-line-format" target="_blank" rel="noopener noreferrer">xyzzyリファレンスマニュアル: ウィンドウ#mode-line-format</a></p><p>JavaScriptなら％じゃなくて$かなぁ、という気はする。</p><p>まぁいい。</p><h3 id="xyzzyのモード行の描画周りを追う" tabindex="-1"><a class="header-anchor" href="#xyzzyのモード行の描画周りを追う"><span>xyzzyのモード行の描画周りを追う</span></a></h3><p>まずはcpp側ではVmode_line_formatという名前で検索するとこれを触っている所がわかる。 描画しているのはdisp.ccの<code>Window::paint_mode_line</code>か。</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token keyword">void</span></span>
<span class="line"><span class="token class-name">Window</span><span class="token double-colon punctuation">::</span><span class="token function">paint_mode_line</span> <span class="token punctuation">(</span>HDC hdc<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line"><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span></span>
<span class="line">  lisp fmt <span class="token operator">=</span> <span class="token function">symbol_value</span> <span class="token punctuation">(</span>Vmode_line_format<span class="token punctuation">,</span> w_bufp<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span></span>
<span class="line">  buffer_info <span class="token function">binfo</span> <span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">,</span> w_bufp<span class="token punctuation">,</span> <span class="token operator">&amp;</span>posp<span class="token punctuation">,</span> <span class="token operator">&amp;</span>w_ime_mode_line<span class="token punctuation">,</span> <span class="token operator">&amp;</span>percentp<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  b <span class="token operator">=</span> binfo<span class="token punctuation">.</span><span class="token function">format</span> <span class="token punctuation">(</span>fmt<span class="token punctuation">,</span> b<span class="token punctuation">,</span> b0 <span class="token operator">+</span> l<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span></span>
<span class="line">  <span class="token comment">// 以下Win32APIによるテキスト描画やfill rectなど</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>という事でbinfo.formatで文字列を書いている。binfoのコンストラクタは単にポインタなどをbinfoのメンバでも参照するだけで値を変えたりはしていなかった。 で、<code>buffer_info::format</code>はbinfo.ccにある。</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line">Char <span class="token operator">*</span></span>
<span class="line">buffer_info<span class="token double-colon punctuation">::</span><span class="token function">format</span> <span class="token punctuation">(</span>lisp fmt<span class="token punctuation">,</span> Char <span class="token operator">*</span>b<span class="token punctuation">,</span> Char <span class="token operator">*</span>be<span class="token punctuation">)</span> <span class="token keyword">const</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">   <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> </span>
<span class="line">  <span class="token keyword">const</span> ucs4_t <span class="token operator">*</span>p <span class="token operator">=</span> <span class="token function">xstring_contents</span> <span class="token punctuation">(</span>fmt<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">const</span> ucs4_t <span class="token operator">*</span><span class="token keyword">const</span> pe <span class="token operator">=</span> p <span class="token operator">+</span> <span class="token function">xstring_length</span> <span class="token punctuation">(</span>fmt<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">while</span> <span class="token punctuation">(</span>p <span class="token operator">&lt;</span> pe <span class="token operator">&amp;&amp;</span> b <span class="token operator">&lt;</span> be<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">      ucs4_t c <span class="token operator">=</span> <span class="token operator">*</span>p<span class="token operator">++</span><span class="token punctuation">;</span></span>
<span class="line">      <span class="token keyword">if</span> <span class="token punctuation">(</span>c <span class="token operator">!=</span> <span class="token char">&#39;%&#39;</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">{</span></span>
<span class="line">        normal_char<span class="token operator">:</span></span>
<span class="line">          <span class="token keyword">if</span> <span class="token punctuation">(</span>b <span class="token operator">&lt;</span> be<span class="token punctuation">)</span> <span class="token operator">*</span>b<span class="token operator">++</span> <span class="token operator">=</span> <span class="token function">Char</span> <span class="token punctuation">(</span>c<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">      <span class="token keyword">else</span></span>
<span class="line">        <span class="token punctuation">{</span></span>
<span class="line">          <span class="token keyword">if</span> <span class="token punctuation">(</span>p <span class="token operator">==</span> pe<span class="token punctuation">)</span></span>
<span class="line">            <span class="token keyword">break</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">          c <span class="token operator">=</span> <span class="token operator">*</span>p<span class="token operator">++</span><span class="token punctuation">;</span></span>
<span class="line">          <span class="token keyword">int</span> pound <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">          <span class="token keyword">if</span> <span class="token punctuation">(</span>c <span class="token operator">==</span> <span class="token char">&#39;#&#39;</span><span class="token punctuation">)</span></span>
<span class="line">            <span class="token punctuation">{</span></span>
<span class="line">              pound <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line">              <span class="token keyword">if</span> <span class="token punctuation">(</span>p <span class="token operator">==</span> pe<span class="token punctuation">)</span></span>
<span class="line">                <span class="token keyword">break</span><span class="token punctuation">;</span></span>
<span class="line">              c <span class="token operator">=</span> <span class="token operator">*</span>p<span class="token operator">++</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">          <span class="token keyword">switch</span> <span class="token punctuation">(</span>c<span class="token punctuation">)</span></span>
<span class="line">            <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">default</span><span class="token operator">:</span></span>
<span class="line">              <span class="token keyword">goto</span> normal_char<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">            <span class="token keyword">case</span> <span class="token char">&#39;*&#39;</span><span class="token operator">:</span></span>
<span class="line">              b <span class="token operator">=</span> <span class="token function">modified</span> <span class="token punctuation">(</span>b<span class="token punctuation">,</span> pound<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">              <span class="token keyword">break</span><span class="token punctuation">;</span></span>
<span class="line">           <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span></span>
<span class="line">           <span class="token punctuation">}</span></span>
<span class="line">      <span class="token punctuation">}</span></span>
<span class="line">   <span class="token punctuation">}</span></span>
<span class="line">   <span class="token keyword">return</span> b<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>という事で一文字ずつ見て真面目にフォーマット処理をしている。</p><p>これに使えるものとして何があるのか、という事を考えるために、buffer_infoのメンバ変数も簡単に見ておく。</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token keyword">class</span> <span class="token class-name">buffer_info</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> Window <span class="token operator">*</span><span class="token keyword">const</span> b_wp<span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">const</span> Buffer <span class="token operator">*</span><span class="token keyword">const</span> b_bufp<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>という事でBufferとWindowから取れる値がだいたい使える物という事になる。</p><p>まぁフォーマット処理は読まなくてもだいたい分かるので、だいたいこっちは分かった。 ではpaint_mode_lineが呼ばれるタイミングも見ておこう。</p><p>検索してみると、<code>Window::redraw_mode_line</code>から呼ばれていて、これは<code>Window::refresh</code>から呼ばれていた。 これは検索するといろいろ引っかかるが、<code>Window::update_window</code>から呼ばれるという事なのかな？ これはWM_PAINTから呼ばれていた。</p><p>WM_PAINT側からたどると、おおまかには毎回redraw_mode_lineまでは呼ばれていそう。</p><p>redraw_mode_lineの中では％とポイントだけで良いか、それとも全部書くかの判定がある。 なかなか細かい最適化ではある。</p><p>ただ自分の用途だと毎回全部redrawでいいかな（hardware renderingだとAndroidは部分更新が実質ない）。</p><h2 id="chrome-skkの辞書登録周りを読む" tabindex="-1"><a class="header-anchor" href="#chrome-skkの辞書登録周りを読む"><span>chrome-skkの辞書登録周りを読む</span></a></h2><p>ユーザー辞書対応をしたいので、chrome-skkの辞書登録周りを読む。</p><p>移植をしている時に、createInnerSKKというのがそれっぽいんじゃないか、という気はしていたので、まずはこれを呼んでいる所を調べる。 conversion_mode.jsの二箇所で呼ばれていた。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">  skk<span class="token punctuation">.</span><span class="token function">lookup</span><span class="token punctuation">(</span>skk<span class="token punctuation">.</span>preedit <span class="token operator">+</span> skk<span class="token punctuation">.</span>okuriPrefix<span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">entries</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>entries<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token operator">...</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">      skk<span class="token punctuation">.</span><span class="token function">createInnerSKK</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>これはlookupで候補が無かったら、という事。もう一つは変換でスペースたくさん押した時か。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">function</span> <span class="token function">conversionMode</span><span class="token punctuation">(</span><span class="token parameter">skk<span class="token punctuation">,</span> keyevent</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>keyevent<span class="token punctuation">.</span>key <span class="token operator">==</span> <span class="token string">&#39; &#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>skk<span class="token punctuation">.</span>entries<span class="token punctuation">.</span>index <span class="token operator">&gt;</span> <span class="token number">2</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      skk<span class="token punctuation">.</span>entries<span class="token punctuation">.</span>index <span class="token operator">+=</span> <span class="token number">7</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">      skk<span class="token punctuation">.</span>entries<span class="token punctuation">.</span>index<span class="token operator">++</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>skk<span class="token punctuation">.</span>entries<span class="token punctuation">.</span>index <span class="token operator">&gt;=</span> skk<span class="token punctuation">.</span>entries<span class="token punctuation">.</span>entries<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      skk<span class="token punctuation">.</span><span class="token function">createInnerSKK</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">   <span class="token operator">...</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>skk.entries.entries.lengthってなんやねん、という気はするが、たぶん変換候補の最後にいったら、って感じと予想するとこれであってそう。</p><p>createInnerSKKは抜粋が難しいが、「【】」とかを表示したりいろいろな処理が入っている。 この辺はどうせ書き直す必要があるのでまあり読む気も起こらないが、ポイントとしてはこの辺はあくまで変換として動いていて、 保存したりはこの辺では無くconversion_mode.jsの方のrecordNewResultのようだ。</p><p>ちなみにrecordNewResultは最終的にはsyncUserDictionaryが呼ばれて以下。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token class-name">Dictionary</span><span class="token punctuation">.</span>prototype<span class="token punctuation">.</span><span class="token function-variable function">syncUserDictionary</span> <span class="token operator">=</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">var</span> userDict <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">.</span>userDict<span class="token punctuation">;</span></span>
<span class="line">  chrome<span class="token punctuation">.</span>storage<span class="token punctuation">.</span>local<span class="token punctuation">.</span><span class="token function">set</span><span class="token punctuation">(</span><span class="token punctuation">{</span> userDict <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>あれ？キーを指定しないのかな？ initは以下のようになっているが。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token class-name">Dictionary</span><span class="token punctuation">.</span>prototype<span class="token punctuation">.</span><span class="token function-variable function">initUserDictionary</span> <span class="token operator">=</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">var</span> self <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">;</span></span>
<span class="line">  chrome<span class="token punctuation">.</span>storage<span class="token punctuation">.</span>local<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&#39;userDict&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">data</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>data<span class="token punctuation">.</span>userDict<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      self<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token punctuation">{</span><span class="token string-property property">&#39;status&#39;</span><span class="token operator">:</span><span class="token string">&#39;loaded_user_dict_from_storage&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">dict_size</span><span class="token operator">:</span> Object<span class="token punctuation">.</span><span class="token function">keys</span><span class="token punctuation">(</span>data<span class="token punctuation">.</span>userDict<span class="token punctuation">)</span><span class="token punctuation">.</span>length<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">      self<span class="token punctuation">.</span>userDict <span class="token operator">=</span> data<span class="token punctuation">.</span>userDict<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>userDictというキーで保存しそうなもんだが、まぁいい。とにかくuserDictはjsonそのまんまっぽいな。 Rhinocsもそれでいいかなぁ。マージとかしようとすると専用コードを書かないといけないだろうが、まぁそのくらいは必要な人がLLMに書いてもらえばいいだろう。</p><h2 id="c-spaceがbooxで来ない問題" tabindex="-1"><a class="header-anchor" href="#c-spaceがbooxで来ない問題"><span>C-SpaceがBOOXで来ない問題</span></a></h2><p>onKeyDownがそもそも来ていない。dispatchKeyEventを見るとACTION_UPは来るがACTION_DOWNは来てない。</p><p>emacsにも記述があって、C-SPC が奪われる関連にはandroid-intercept-control-space というフラグでちょっと処理しているみたいな事を言っている。</p><p><a href="https://www.gnu.org/software/emacs/manual/html_node/emacs/Android-Windowing.html" target="_blank" rel="noopener noreferrer">Android Windowing (GNU Emacs Manual)</a></p><p>このフラグでコードを確認するとEmacsView.javaに以下のコードが。</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code class="language-java"><span class="line">  <span class="token annotation punctuation">@Override</span></span>
<span class="line">  <span class="token keyword">public</span> <span class="token keyword">boolean</span></span>
<span class="line">  onKeyPreIme <span class="token punctuation">(</span><span class="token keyword">int</span> keyCode<span class="token punctuation">,</span> <span class="token class-name">KeyEvent</span> event<span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">/* Several Android systems intercept key events representing</span>
<span class="line">       C-SPC.  Avert this by detecting C-SPC events here and relaying</span>
<span class="line">       them directly to onKeyDown.</span>
<span class="line"></span>
<span class="line">       Make this optional though, since some input methods also</span>
<span class="line">       leverage C-SPC as a shortcut for switching languages.  */</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token punctuation">(</span>keyCode <span class="token operator">==</span> <span class="token class-name">KeyEvent</span><span class="token punctuation">.</span><span class="token constant">KEYCODE_SPACE</span></span>
<span class="line">	 <span class="token operator">&amp;&amp;</span> <span class="token punctuation">(</span>window<span class="token punctuation">.</span>eventModifiers <span class="token punctuation">(</span>event<span class="token punctuation">)</span></span>
<span class="line">	     <span class="token operator">&amp;</span> <span class="token class-name">KeyEvent</span><span class="token punctuation">.</span><span class="token constant">META_CTRL_MASK</span><span class="token punctuation">)</span> <span class="token operator">!=</span> <span class="token number">0</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token operator">&amp;&amp;</span> <span class="token operator">!</span><span class="token class-name">EmacsNative</span><span class="token punctuation">.</span>shouldForwardCtrlSpace <span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">      <span class="token keyword">return</span> onKeyDown <span class="token punctuation">(</span>keyCode<span class="token punctuation">,</span> event<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">return</span> <span class="token keyword">super</span><span class="token punctuation">.</span>onKeyPreIme <span class="token punctuation">(</span>keyCode<span class="token punctuation">,</span> event<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>あれ？action見てないんだが。これだとupとdown両方送ってしまうのでは？downでtrueを返しておけばupは来ないのかな？</p><p>onKeyPreImeを調べてみたがこれもBOOXではC-SpaceはACTION_UPしか来ない模様。</p><p><a href="./Rhinocs.html">Rhinocs</a>ではC-SpaceのACTION_DOWNが来て無くてACTION_UPが来た時だけonKeyDownを呼ぶようにしよう。</p><h2 id="マーカーの調査" tabindex="-1"><a class="header-anchor" href="#マーカーの調査"><span>マーカーの調査</span></a></h2><p>eval_regionが欲しくなったので、マーカーを実装したい。という事で既存実装を見る。 たぶんBufferが持たないと駄目なんだよな。</p><p>xyzzyの実装を軽く見る。まず普段使う奴はset-mark-commandか。</p><div class="language-lisp line-numbers-mode" data-highlighter="prismjs" data-ext="lisp"><pre><code class="language-lisp"><span class="line"><span class="token punctuation">(</span><span class="token defun"><span class="token keyword">defun</span> <span class="token function">set-mark-command</span> <span class="token punctuation">(</span><span class="token arguments"></span><span class="token punctuation">)</span></span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token interactive keyword">interactive</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token car">set-mark</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token keyword">unless</span> *executing-macro*</span>
<span class="line">    <span class="token punctuation">(</span><span class="token keyword">message</span> <span class="token string">&quot;Mark set&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token boolean">t</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>set-markはcpp側で実装されている。move.cc。</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line">lisp</span>
<span class="line"><span class="token function">Fset_mark</span> <span class="token punctuation">(</span>lisp point<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">  Window <span class="token operator">*</span>wp <span class="token operator">=</span> <span class="token function">selected_window</span> <span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>point <span class="token operator">||</span> point <span class="token operator">==</span> Qnil<span class="token punctuation">)</span></span>
<span class="line">    wp<span class="token operator">-&gt;</span>w_mark <span class="token operator">=</span> wp<span class="token operator">-&gt;</span>w_point<span class="token punctuation">.</span>p_point<span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>point <span class="token operator">==</span> Qt<span class="token punctuation">)</span></span>
<span class="line">    wp<span class="token operator">-&gt;</span>w_mark <span class="token operator">=</span> NO_MARK_SET<span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">else</span></span>
<span class="line">    wp<span class="token operator">-&gt;</span>w_mark <span class="token operator">=</span> wp<span class="token operator">-&gt;</span>w_bufp<span class="token operator">-&gt;</span><span class="token function">coerce_to_restricted_point</span> <span class="token punctuation">(</span>point<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> Qt<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>あれ？wpに保存しているな。バッファの方で編集作業があるとどうなるのだろう？ しかもなんかマーカーオブジェクトじゃなくて単にpointを入れてるように見えるな。</p><p>なんかset_markとset_markerがあってほとんと同じに見えてややこしいな。 Fset_markがマークをウィンドウにセットし、Fset_markerはマーカーの方の位置を更新する。</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line">lisp</span>
<span class="line"><span class="token function">Fset_marker</span> <span class="token punctuation">(</span>lisp marker<span class="token punctuation">,</span> lisp point<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">  Window <span class="token operator">*</span>wp <span class="token operator">=</span> <span class="token function">selected_window</span> <span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  Buffer <span class="token operator">*</span>bp <span class="token operator">=</span> wp<span class="token operator">-&gt;</span>w_bufp<span class="token punctuation">;</span></span>
<span class="line">  bp<span class="token operator">-&gt;</span><span class="token function">valid_marker_p</span> <span class="token punctuation">(</span>marker<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>point <span class="token operator">||</span> point <span class="token operator">==</span> Qnil<span class="token punctuation">)</span></span>
<span class="line">    <span class="token function">xmarker_point</span> <span class="token punctuation">(</span>marker<span class="token punctuation">)</span> <span class="token operator">=</span> wp<span class="token operator">-&gt;</span>w_point<span class="token punctuation">.</span>p_point<span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">else</span></span>
<span class="line">    <span class="token function">xmarker_point</span> <span class="token punctuation">(</span>marker<span class="token punctuation">)</span> <span class="token operator">=</span> bp<span class="token operator">-&gt;</span><span class="token function">coerce_to_restricted_point</span> <span class="token punctuation">(</span>point<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> marker<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>ふむ、markerの位置を更新するだけか。set_markでmarkerを使わずに位置だけを覚えているのは違和感があるが、他のエディタもそうなんだろうか？</p><p>lemを見てみるとmark-setか？</p><div class="language-lisp line-numbers-mode" data-highlighter="prismjs" data-ext="lisp"><pre><code class="language-lisp"><span class="line"><span class="token punctuation">(</span><span class="token car">define-key</span> *global-keymap* <span class="token string">&quot;C-Space&quot;</span> <span class="token quoted-symbol variable symbol">&#39;mark-set</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token punctuation">(</span><span class="token car">define-command</span> mark-set <span class="token punctuation">(</span><span class="token car">p</span><span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token lisp-property property">:universal-nil</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token string">&quot;Sets a mark at the current cursor position.&quot;</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token keyword">if</span> p</span>
<span class="line">      <span class="token punctuation">(</span><span class="token car">move-point</span> <span class="token punctuation">(</span><span class="token car">current-point</span><span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token car">pop-buffer-point</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">      <span class="token punctuation">(</span><span class="token car">progn</span></span>
<span class="line">        <span class="token punctuation">(</span><span class="token car">set-cursor-mark</span> <span class="token punctuation">(</span><span class="token car">current-point</span><span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token car">current-point</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">(</span><span class="token keyword">message</span> <span class="token string">&quot;Mark set&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>set-cursor-markとそこから呼ばれているset-current-mark。</p><div class="language-lisp line-numbers-mode" data-highlighter="prismjs" data-ext="lisp"><pre><code class="language-lisp"><span class="line"><span class="token punctuation">(</span><span class="token car">defmethod</span> set-cursor-mark <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token car">cursor</span> cursor<span class="token punctuation">)</span> point<span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token car">set-current-mark</span> point<span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token car">push-buffer-point</span> point<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token punctuation">(</span><span class="token defun"><span class="token keyword">defun</span> <span class="token function">set-current-mark</span> <span class="token punctuation">(</span><span class="token arguments"><span class="token argument variable">point</span></span><span class="token punctuation">)</span></span></span>
<span class="line">  <span class="token string">&quot;Set &#39;point&#39; to the current mark.&quot;</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token keyword">let</span> <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token car">buffer</span> <span class="token punctuation">(</span><span class="token car">point-buffer</span> point<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">(</span><span class="token car">setf</span> <span class="token punctuation">(</span><span class="token car">buffer-mark</span> buffer<span class="token punctuation">)</span> point<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">  point<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>名前から推測するにbufferのマーカーの位置を更新している。 こっちの方が普通だよな。</p><p>emacsのコードも簡単に確認しておこう。</p><div class="language-lisp line-numbers-mode" data-highlighter="prismjs" data-ext="lisp"><pre><code class="language-lisp"><span class="line"><span class="token punctuation">(</span><span class="token defun"><span class="token keyword">defun</span> <span class="token function">set-mark-command</span> <span class="token punctuation">(</span><span class="token arguments"><span class="token argument variable">arg</span></span><span class="token punctuation">)</span></span></span>
<span class="line">...</span>
<span class="line"> <span class="token punctuation">(</span><span class="token car">push-mark-command</span> <span class="token boolean">nil</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token punctuation">(</span><span class="token defun"><span class="token keyword">defun</span> <span class="token function">push-mark-command</span> <span class="token punctuation">(</span><span class="token arguments"><span class="token argument variable">arg</span> <span class="token other-marker-vars"><span class="token lisp-marker">&amp;optional</span> <span class="token argument variable">nomsg</span></span></span><span class="token punctuation">)</span></span></span>
<span class="line">...</span>
<span class="line">  <span class="token punctuation">(</span><span class="token car">push-mark</span> <span class="token boolean">nil</span> nomsg <span class="token boolean">t</span><span class="token punctuation">)</span></span>
<span class="line">...<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token punctuation">(</span><span class="token defun"><span class="token keyword">defun</span> <span class="token function">push-mark</span> <span class="token punctuation">(</span><span class="token arguments"><span class="token other-marker-vars"><span class="token lisp-marker">&amp;optional</span> <span class="token argument variable">location</span> <span class="token argument variable">nomsg</span> <span class="token argument variable">activate</span></span></span><span class="token punctuation">)</span></span></span>
<span class="line">...</span>
<span class="line">  <span class="token punctuation">(</span><span class="token car">set-marker</span> <span class="token punctuation">(</span><span class="token car">mark-marker</span><span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token keyword">or</span> location <span class="token punctuation">(</span><span class="token car">point</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token car">current-buffer</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">...<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>set-mark-commandといいつつpush-mark-commandしていて、これは結局set-markerを呼んでいる。 やっぱりxyzzyの実装が特殊だな。</p><p>ただxyzzyにもmake-markerとかset-markerはあるし、xyzzyのコードが一番読みやすいので、xyzzyのmake-markerとかを真似する感じにするかな。</p><p>ちなみにマーカーとマークの用語については、emacs lispのマニュアルの30.7に記述がある。</p><p><a href="https://web.sfc.wide.ad.jp/~sagawa/gnujdoc/elisp-manual-20-2.5/elisp-ja_31.html" target="_blank" rel="noopener noreferrer">GNU Emacs Lispリファレンスマニュアル: Markers</a></p><p>バッファ一つにつき１つある特別なマーカーをマークと呼ぶらしい。</p><h3 id="バッファ変更時のmarkerの移動処理" tabindex="-1"><a class="header-anchor" href="#バッファ変更時のmarkerの移動処理"><span>バッファ変更時のmarkerの移動処理</span></a></h3><p>マーカーで一番重要なのはバッファが変更されると移動する、という所だ。 そこをxyzzyでどうやっているかを見てみよう。</p><p>まずマーカーを作る所でバッファのどこにぶら下げているかを見てみる。</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line">lisp</span>
<span class="line"><span class="token function">Fmake_marker</span> <span class="token punctuation">(</span>lisp buffer<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">  Buffer <span class="token operator">*</span>bp <span class="token operator">=</span> <span class="token class-name">Buffer</span><span class="token double-colon punctuation">::</span><span class="token function">coerce_to_buffer</span> <span class="token punctuation">(</span>buffer<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  lisp marker <span class="token operator">=</span> <span class="token function">make_marker</span> <span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  bp<span class="token operator">-&gt;</span>lmarkers <span class="token operator">=</span> <span class="token function">Fcons</span> <span class="token punctuation">(</span>marker<span class="token punctuation">,</span> bp<span class="token operator">-&gt;</span>lmarkers<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token function">xmarker_buffer</span> <span class="token punctuation">(</span>marker<span class="token punctuation">)</span> <span class="token operator">=</span> bp<span class="token punctuation">;</span></span>
<span class="line">  <span class="token function">xmarker_point</span> <span class="token punctuation">(</span>marker<span class="token punctuation">)</span> <span class="token operator">=</span> NO_MARK_SET<span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> marker<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>lmarkersだな。これをinsdel.cc内でいじっている場所を見ると、以下の２つのメソッドで更新している。</p><ul><li>Buffer::adjust_insertion</li><li>Buffer::adjust_deletion</li></ul><p>おお、素直だな。 adjust_insertionを軽く見ておく。</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token keyword">void</span></span>
<span class="line"><span class="token class-name">Buffer</span><span class="token double-colon punctuation">::</span><span class="token function">adjust_insertion</span> <span class="token punctuation">(</span><span class="token keyword">const</span> Point <span class="token operator">&amp;</span>point<span class="token punctuation">,</span> <span class="token keyword">int</span> size<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">  point_t opoint <span class="token operator">=</span> point<span class="token punctuation">.</span>p_point<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">define</span> <span class="token macro-name function">ADJINS</span><span class="token expression"><span class="token punctuation">(</span>P<span class="token punctuation">)</span> <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token punctuation">(</span>P<span class="token punctuation">)</span> <span class="token operator">&gt;</span> opoint<span class="token punctuation">)</span> <span class="token punctuation">(</span>P<span class="token punctuation">)</span> <span class="token operator">+=</span> size</span></span></span>
<span class="line"><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span></span>
<span class="line">  <span class="token keyword">for</span> <span class="token punctuation">(</span>lisp marker <span class="token operator">=</span> lmarkers<span class="token punctuation">;</span> <span class="token function">consp</span> <span class="token punctuation">(</span>marker<span class="token punctuation">)</span><span class="token punctuation">;</span> marker <span class="token operator">=</span> <span class="token function">xcdr</span> <span class="token punctuation">(</span>marker<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">      lisp x <span class="token operator">=</span> <span class="token function">xcar</span> <span class="token punctuation">(</span>marker<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">      <span class="token function">ADJINS</span> <span class="token punctuation">(</span><span class="token function">xmarker_point</span> <span class="token punctuation">(</span>x<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>素直だな。deleteの方はまぁいいだろう。 これをinsert関連の後で毎回呼ぶ感じか。</p><h2 id="エコー領域の調査" tabindex="-1"><a class="header-anchor" href="#エコー領域の調査"><span>エコー領域の調査</span></a></h2><p>そろそろミニバッファを実装するか、という事でまず既存実装の振る舞いを調べて見た所、どうもミニバッファは入力の時だけに出来て、 表示だけのはエコー領域と言って違うっぽい事がemacs lispのマニュアルにかかれていた。</p><p>という事で今欲しいのはエコー領域なので、エコー領域を調べる</p><h3 id="emacs-lispのリファレンスのエコー領域" tabindex="-1"><a class="header-anchor" href="#emacs-lispのリファレンスのエコー領域"><span>emacs lispのリファレンスのエコー領域</span></a></h3><p>とりあえずemacs lispのリファレンスを読む所から。</p><p><a href="https://web.sfc.wide.ad.jp/~sagawa/gnujdoc/elisp-manual-20-2.5/elisp-ja_39.html#SEC623" target="_blank" rel="noopener noreferrer">GNU Emacs Lispリファレンスマニュアル: Display</a></p><p>ふむふむ、message関数で表示する、nilを渡すとクリア、か。</p><h3 id="xyzzyのエコー領域" tabindex="-1"><a class="header-anchor" href="#xyzzyのエコー領域"><span>xyzzyのエコー領域</span></a></h3><p>まずはdefun messageを検索するとmisc.lで以下が引っかかる。</p><div class="language-lisp line-numbers-mode" data-highlighter="prismjs" data-ext="lisp"><pre><code class="language-lisp"><span class="line"><span class="token punctuation">(</span><span class="token defun"><span class="token keyword">defun</span> <span class="token function">message</span> <span class="token punctuation">(</span><span class="token arguments"><span class="token argument variable">fmt</span> <span class="token rest-vars"><span class="token lisp-marker">&amp;rest</span> <span class="token argument variable">args</span></span></span><span class="token punctuation">)</span></span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token car">terpri</span> *status-window*<span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token car">apply</span> <span class="token quoted-symbol variable symbol">#&#39;format</span> *status-window* fmt args<span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token car">terpri</span> *status-window*<span class="token punctuation">)</span></span>
<span class="line">  <span class="token boolean">t</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>terpriってなんだ？Fterpriで検索するとlprint.ccがそれっぽいか。</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line">lisp</span>
<span class="line"><span class="token function">Fterpri</span> <span class="token punctuation">(</span>lisp stream<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">writec_stream</span> <span class="token punctuation">(</span><span class="token function">output_stream</span> <span class="token punctuation">(</span>stream<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token char">&#39;\\n&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> Qnil<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>改行をprintするだけか。</p><p><code>(message &quot;hoge&quot;)</code> を実行してみたら、ステータスバーに書かれた。おぉ、emacsとは違って別領域に書かれるのか。 こっちの方が筋が良いとは思うが、Androidで二行使うのはいまいちなのでemacsのように下の行を使う方が良さそうか。</p><h2 id="skk-modeの変換周辺を読む" tabindex="-1"><a class="header-anchor" href="#skk-modeの変換周辺を読む"><span>skk-modeの変換周辺を読む</span></a></h2><p>エディタじゃないけどまぁここでいいでしょう。</p><p>chrome-skkの移植はなんとなくpreeditが動いているあたりまでは来た。ただsetCompositionとかが空なのでこの辺をどうするか考えるタイミングに来た。</p><p>という事で<a href="https://github.com/loyaltouch/Skk-Mode/tree/master" target="_blank" rel="noopener noreferrer">loyaltouch/Skk-Mode: xyzzy-skk-mode</a>のskk.lを読む。</p><p>大文字のAとかが何にバインドされているかを調べると、j-set-henkan-pointという関数らしい。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">(define-key map #\\A &#39;j-set-henkan-point)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>j-set-henkan-pointで変換が始まり、j-henkanとかj-kakuteiで処理される感じか？</p><p>j-set-henkan-pointを見ると、</p><ol><li>j-set-henkan-point-subrを呼ぶ（ここで▽をinsertしたり変換開始のpointを覚えたりj-henkan-onをセットしたり）</li><li>j-okuriganaや撥音などを処理</li><li>必要ならj-henkanを呼び出す</li></ol><p>j-henkanを簡単に見ると</p><ol><li>j-change-markerする</li><li>j-henkan-activeをtにする</li><li>j-henkan-show-candidateを呼ぶ</li><li>(delete-region j-henkan-start-point j-henkan-end-point)を呼ぶ</li><li>(insert new-word)する</li><li>kakuteなら(j-kakute new-word)する</li></ol><p>ここまでの感じだと、chrome-skkでpreeditと呼んでいるのがだいたいj-set-henkan-pointに対応し、setCompositionやclearCompositionとconversionの処理をしているのがj-henkanっぽい。 chrome-skkの移植として参考にすべきはj-henkanのあたりか。</p><p>Rhinocs側で実装する必要がある関数を抜き出そう。</p><ul><li>(point) <ul><li>j-kana-start-pointとかj-henkan-start-pointとかを覚えている</li></ul></li><li>delete-backward-char</li><li>delete-region</li></ul><p>まずはこの辺か。</p><h2 id="next-lineでカラムの位置を覚えておくメカニズム" tabindex="-1"><a class="header-anchor" href="#next-lineでカラムの位置を覚えておくメカニズム"><span>next-lineでカラムの位置を覚えておくメカニズム</span></a></h2><p>行を下に移動していく時に、文字が少ない行を通ってもその次にまた文字が多い行にうつる時には前のカラムに移動していく。 そのためには移動開始時のカラムを覚えておくメカニズムが必要という事だと思う。</p><p>一方でこのカラムは例えば水平方向に移動した時などはリセットされないと変な事になる。けれどどこでリセットするべきかはそこまで自明でもない。</p><p>その辺のコードを読んでいく。</p><h3 id="xyzzyでのgoal-column" tabindex="-1"><a class="header-anchor" href="#xyzzyでのgoal-column"><span>xyzzyでのgoal-column</span></a></h3><p>next-lineはcmds.lに定義されている。</p><div class="language-lisp line-numbers-mode" data-highlighter="prismjs" data-ext="lisp"><pre><code class="language-lisp"><span class="line"><span class="token punctuation">(</span><span class="token defun"><span class="token keyword">defun</span> <span class="token function">next-line-1</span> <span class="token punctuation">(</span><span class="token arguments"><span class="token argument variable">n</span> <span class="token argument variable">line-mover</span> <span class="token argument variable">column-mover</span></span><span class="token punctuation">)</span></span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token keyword">let</span> <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token car">goal-column</span> <span class="token punctuation">(</span><span class="token car">goal-column</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">(</span><span class="token car">moved</span> <span class="token punctuation">(</span><span class="token car">funcall</span> line-mover n<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">(</span><span class="token keyword">cond</span> <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token keyword">and</span> next-line-add-newlines</span>
<span class="line">		<span class="token punctuation">(</span><span class="token car">plusp</span> n<span class="token punctuation">)</span></span>
<span class="line">		<span class="token punctuation">(</span><span class="token keyword">not</span> <span class="token punctuation">(</span><span class="token car">eql</span> moved n<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	   <span class="token punctuation">(</span><span class="token car">goto-char</span> <span class="token punctuation">(</span><span class="token car">point-max</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	   <span class="token punctuation">(</span><span class="token car">insert</span> #\\LFD <span class="token punctuation">(</span><span class="token car">-</span> n <span class="token punctuation">(</span><span class="token keyword">or</span> moved <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	   <span class="token punctuation">(</span><span class="token car">set-goal-column</span> goal-column<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	  <span class="token punctuation">(</span><span class="token car">moved</span></span>
<span class="line">	   <span class="token punctuation">(</span><span class="token car">funcall</span> column-mover goal-column<span class="token punctuation">)</span></span>
<span class="line">	   <span class="token punctuation">(</span><span class="token car">set-goal-column</span> goal-column<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	  <span class="token punctuation">(</span><span class="token boolean">t</span> <span class="token boolean">nil</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token punctuation">(</span><span class="token defun"><span class="token keyword">defun</span> <span class="token function">next-line</span> <span class="token punctuation">(</span><span class="token arguments"><span class="token other-marker-vars"><span class="token lisp-marker">&amp;optional</span> <span class="token varform"><span class="token punctuation">(</span><span class="token car">n</span> <span class="token number">1</span><span class="token punctuation">)</span></span></span></span><span class="token punctuation">)</span></span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token interactive keyword">interactive</span> <span class="token string">&quot;p&quot;</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token car">next-line-1</span> n <span class="token quoted-symbol variable symbol">#&#39;forward-line</span> <span class="token quoted-symbol variable symbol">#&#39;goto-column</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>goto-columnなんてのがあるのか。まぁいいとして、基本的には</p><ol><li>next-line-1の先頭で(goal-column)で取得して</li><li>next-line-1の最後にset-goal-columnというのでこれを保存している</li></ol><p>Fset_goal_columnはmove.ccにあり、以下のようにwpのw_goal_columnに保存している。</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line">lisp</span>
<span class="line"><span class="token function">Fset_goal_column</span> <span class="token punctuation">(</span>lisp goal<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">long</span> n <span class="token operator">=</span> <span class="token function">fixnum_value</span> <span class="token punctuation">(</span>goal<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>n <span class="token operator">&lt;</span> <span class="token number">0</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token function">FErange_error</span> <span class="token punctuation">(</span>goal<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  Window <span class="token operator">*</span>wp <span class="token operator">=</span> <span class="token function">selected_window</span> <span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>wp<span class="token operator">-&gt;</span>w_goal_column <span class="token operator">!=</span> n<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">      wp<span class="token operator">-&gt;</span>w_goal_column <span class="token operator">=</span> n<span class="token punctuation">;</span></span>
<span class="line">      wp<span class="token operator">-&gt;</span>w_disp_flags <span class="token operator">|=</span> Window<span class="token double-colon punctuation">::</span>WDF_SET_GOAL_COLUMN<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  wp<span class="token operator">-&gt;</span>w_disp_flags <span class="token operator">&amp;=</span> <span class="token operator">~</span>Window<span class="token double-colon punctuation">::</span>WDF_GOAL_COLUMN<span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> Qt<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>あとはこれをリセットしている場所をなんとなく検索して調べれば良さそうか。 ざっと見るとやっておいた方が良さそうなのは以下。</p><ul><li>set_buffer</li><li>reframe（ようするにonPaintみたいなもの）でWDF_GOAL_COLUMNフラグが立ってたら</li></ul><p>だいたいWDF_GOAL_COLUMNフラグを立てるという事にしてそう。そうか。0がgoalかどうかがわからないのでフラグが必要なのか。 そしてこれはforward_charなどで立てている。ふむふむ。</p><p>ちなみにフラグが立ってる時は、wpのpointから計算している。</p><div class="language-lisp line-numbers-mode" data-highlighter="prismjs" data-ext="lisp"><pre><code class="language-lisp"><span class="line">lisp</span>
<span class="line">Fgoal_column <span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">{</span>
<span class="line">  Window *wp = selected_window <span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token comment">;</span></span>
<span class="line">  if <span class="token punctuation">(</span><span class="token car">wp-&gt;w_disp_flags</span> &amp; Window:<span class="token lisp-property property">:WDF_GOAL_COLUMN</span><span class="token punctuation">)</span></span>
<span class="line">    {</span>
<span class="line">      wp-&gt;w_goal_column = <span class="token punctuation">(</span><span class="token car">wp-&gt;w_bufp-&gt;b_fold_columns</span> == Buffer:<span class="token lisp-property property">:FOLD_NONE</span></span>
<span class="line">                           ? wp-&gt;w_bufp-&gt;point_column <span class="token punctuation">(</span><span class="token car">wp-&gt;w_point</span><span class="token punctuation">)</span></span>
<span class="line">                           : wp-&gt;w_bufp-&gt;folded_point_column <span class="token punctuation">(</span><span class="token car">wp-&gt;w_point</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token comment">;</span></span>
<span class="line">      wp-&gt;w_disp_flags &amp;= ~Window:<span class="token lisp-property property">:WDF_GOAL_COLUMN</span><span class="token comment">;</span></span>
<span class="line">    }</span>
<span class="line">  return make_fixnum <span class="token punctuation">(</span><span class="token car">wp-&gt;w_goal_column</span><span class="token punctuation">)</span><span class="token comment">;</span></span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="lemのnext-line周辺を読む" tabindex="-1"><a class="header-anchor" href="#lemのnext-line周辺を読む"><span>lemのnext-line周辺を読む</span></a></h3><p>move.lispに以下のようなコードがある。</p><div class="language-lisp line-numbers-mode" data-highlighter="prismjs" data-ext="lisp"><pre><code class="language-lisp"><span class="line"><span class="token punctuation">(</span><span class="token defun"><span class="token keyword">defun</span> <span class="token function">next-line-aux</span> <span class="token punctuation">(</span><span class="token arguments"><span class="token argument variable">n</span></span>
<span class="line">                      <span class="token argument variable">point-column-fn</span></span>
<span class="line">                      <span class="token argument variable">forward-line-fn</span></span>
<span class="line">                      <span class="token argument variable">move-to-column-fn</span></span><span class="token punctuation">)</span></span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token car">continue-flag</span> <span class="token lisp-property property">:next-line</span><span class="token punctuation">)</span></span>
<span class="line">      <span class="token punctuation">(</span><span class="token keyword">unless</span> <span class="token punctuation">(</span><span class="token keyword">not</span> <span class="token punctuation">(</span><span class="token keyword">null</span> <span class="token punctuation">(</span><span class="token car">cursor-saved-column</span> <span class="token punctuation">(</span><span class="token car">current-point</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">(</span><span class="token car">log</span><span class="token lisp-property property">:error</span> <span class="token string">&quot;asseriton error: (not (null (cursor-saved-column (current-point))))&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">      <span class="token punctuation">(</span><span class="token car">setf</span> <span class="token punctuation">(</span><span class="token car">cursor-saved-column</span> <span class="token punctuation">(</span><span class="token car">current-point</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">            <span class="token punctuation">(</span><span class="token car">funcall</span> point-column-fn <span class="token punctuation">(</span><span class="token car">current-point</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token keyword">unless</span> <span class="token punctuation">(</span><span class="token car">prog1</span> <span class="token punctuation">(</span><span class="token car">funcall</span> forward-line-fn <span class="token punctuation">(</span><span class="token car">current-point</span><span class="token punctuation">)</span> n<span class="token punctuation">)</span></span>
<span class="line">            <span class="token punctuation">(</span><span class="token car">funcall</span> move-to-column-fn <span class="token punctuation">(</span><span class="token car">current-point</span><span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token car">cursor-saved-column</span> <span class="token punctuation">(</span><span class="token car">current-point</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">(</span><span class="token keyword">cond</span> <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token car">plusp</span> n<span class="token punctuation">)</span></span>
<span class="line">           <span class="token punctuation">(</span><span class="token car">move-to-end-of-buffer</span><span class="token punctuation">)</span></span>
<span class="line">           <span class="token punctuation">(</span><span class="token keyword">error</span> <span class="token quoted-symbol variable symbol">&#39;end-of-buffer</span> <span class="token lisp-property property">:point</span> <span class="token punctuation">(</span><span class="token car">current-point</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">          <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token car">minusp</span> n<span class="token punctuation">)</span></span>
<span class="line">           <span class="token punctuation">(</span><span class="token car">move-to-beginning-of-buffer</span><span class="token punctuation">)</span></span>
<span class="line">           <span class="token punctuation">(</span><span class="token keyword">error</span> <span class="token quoted-symbol variable symbol">&#39;beginning-of-buffer</span> <span class="token lisp-property property">:point</span> <span class="token punctuation">(</span><span class="token car">current-point</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token punctuation">(</span><span class="token car">define-command</span> <span class="token punctuation">(</span><span class="token car">next-line</span> <span class="token punctuation">(</span><span class="token lisp-property property">:advice-classes</span> movable-advice<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">(</span>&amp;optional n<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token lisp-property property">:universal</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token string">&quot;Move the cursor to next line.&quot;</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token car">next-line-aux</span> n</span>
<span class="line">                 <span class="token quoted-symbol variable symbol">#&#39;point-virtual-line-column</span></span>
<span class="line">                 <span class="token quoted-symbol variable symbol">#&#39;move-to-next-virtual-line</span></span>
<span class="line">                 <span class="token quoted-symbol variable symbol">#&#39;move-to-virtual-line-column</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>なんとなく見ると、cursor-saved-columnがそれっぽいか？continue-flagというのがどう立つのかいまいちわからんが。 これがfalseの時だけsetfしているように見えるが。クリアをどうしているか問題を知りたい場合はこれを誰がセットしているかを知る必要があるが、 <code>:next-line</code>で検索しても引っかからず。うーん、わからん。</p><p>なお、sursor-saved-columnはcursors.lispに以下のような定義がある。</p><div class="language-lisp line-numbers-mode" data-highlighter="prismjs" data-ext="lisp"><pre><code class="language-lisp"><span class="line"><span class="token punctuation">(</span><span class="token car">defclass</span> cursor <span class="token punctuation">(</span><span class="token car">point</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token car">saved-column</span> <span class="token lisp-property property">:initform</span> <span class="token boolean">nil</span></span>
<span class="line">                 <span class="token lisp-property property">:accessor</span> cursor-saved-column<span class="token punctuation">)</span></span>
<span class="line">   ...<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="バッファのpointとwindowのオフセット" tabindex="-1"><a class="header-anchor" href="#バッファのpointとwindowのオフセット"><span>バッファのpointとwindowのオフセット</span></a></h2><p>画面にはバッファの一部が描かれる。 バッファの特定の行数の特定の文字から描かれる感じと思うが、半角-全角的な問題があるので単純に文字数とはならない。</p><p>この辺をどう扱っているかを見てみる。</p><p>コードを全部読んでいくよりも、特定の処理を追っていく事でさしあたって必要な程度の理解を目指す。</p><h3 id="行内を右に一文字移動する" tabindex="-1"><a class="header-anchor" href="#行内を右に一文字移動する"><span>行内を右に一文字移動する</span></a></h3><p>一番単純なケースとして、右に一文字移動するが次の行には行かない場合を見てみる。 とりあえずforward-charを見ていく感じか。</p><p>xyzzyならFforward_charで検索すると良さそう。これはmove.cc。</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line">lisp</span>
<span class="line"><span class="token function">Fforward_char</span> <span class="token punctuation">(</span>lisp n<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">  Window <span class="token operator">*</span>wp <span class="token operator">=</span> <span class="token function">selected_window</span> <span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  wp<span class="token operator">-&gt;</span>w_disp_flags <span class="token operator">|=</span> Window<span class="token double-colon punctuation">::</span>WDF_GOAL_COLUMN<span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token function">boole</span> <span class="token punctuation">(</span>wp<span class="token operator">-&gt;</span>w_bufp<span class="token operator">-&gt;</span><span class="token function">forward_char</span> <span class="token punctuation">(</span>wp<span class="token operator">-&gt;</span>w_point<span class="token punctuation">,</span></span>
<span class="line">                                          <span class="token punctuation">(</span><span class="token operator">!</span>n <span class="token operator">||</span> n <span class="token operator">==</span> Qnil<span class="token punctuation">)</span> <span class="token operator">?</span> <span class="token number">1</span> <span class="token operator">:</span> <span class="token function">fixnum_value</span> <span class="token punctuation">(</span>n<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Bufferのforward_charが呼ばれているが、渡しているのはwpのw_point。 w_pointとかはPoint構造体で以下みたいになっている。</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token keyword">struct</span> <span class="token class-name">Point</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">  point_t p_point<span class="token punctuation">;</span></span>
<span class="line">  Chunk <span class="token operator">*</span>p_chunk<span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">int</span> p_offset<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  Char <span class="token function">ch</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">const</span><span class="token punctuation">;</span></span>
<span class="line">  Char <span class="token operator">&amp;</span><span class="token function">ch</span> <span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  Char <span class="token function">prevch</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">const</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>point_tは単なるlong。p_pointはチャンクのはじめの位置で、p_offsetはチャンク内のオフセットか。</p><p>Buffer::forward_charは適当に抜粋すると以下（dが正の方だけ抜き出す）。</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token keyword">int</span></span>
<span class="line"><span class="token class-name">Buffer</span><span class="token double-colon punctuation">::</span><span class="token function">forward_char</span> <span class="token punctuation">(</span>Point <span class="token operator">&amp;</span>point<span class="token punctuation">,</span> <span class="token keyword">long</span> ncp<span class="token punctuation">)</span> <span class="token keyword">const</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">long</span> d <span class="token operator">=</span> <span class="token function">min</span> <span class="token punctuation">(</span><span class="token function">max</span> <span class="token punctuation">(</span>point<span class="token punctuation">.</span>p_point <span class="token operator">+</span> ncp<span class="token punctuation">,</span> b_contents<span class="token punctuation">.</span>p1<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">                b_contents<span class="token punctuation">.</span>p2<span class="token punctuation">)</span> <span class="token operator">-</span> point<span class="token punctuation">.</span>p_point<span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">int</span> f <span class="token operator">=</span> d <span class="token operator">==</span> ncp<span class="token punctuation">;</span></span>
<span class="line">  Chunk <span class="token operator">*</span>cp <span class="token operator">=</span> point<span class="token punctuation">.</span>p_chunk<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">      <span class="token keyword">while</span> <span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">{</span></span>
<span class="line">          <span class="token keyword">int</span> head_cp <span class="token operator">=</span> <span class="token function">count_code_points</span> <span class="token punctuation">(</span>cp<span class="token operator">-&gt;</span>c_text<span class="token punctuation">,</span> point<span class="token punctuation">.</span>p_offset<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">          <span class="token keyword">int</span> rest_cp <span class="token operator">=</span> cp<span class="token operator">-&gt;</span>c_nchars <span class="token operator">-</span> head_cp<span class="token punctuation">;</span></span>
<span class="line">          <span class="token keyword">if</span> <span class="token punctuation">(</span>d <span class="token operator">&lt;=</span> rest_cp<span class="token punctuation">)</span></span>
<span class="line">            <span class="token punctuation">{</span></span>
<span class="line">              <span class="token keyword">int</span> cu <span class="token operator">=</span> <span class="token function">chunk_forward_cp</span> <span class="token punctuation">(</span>cp<span class="token operator">-&gt;</span>c_text<span class="token punctuation">,</span> cp<span class="token operator">-&gt;</span>c_used<span class="token punctuation">,</span></span>
<span class="line">                                         point<span class="token punctuation">.</span>p_offset<span class="token punctuation">,</span> <span class="token keyword">int</span> <span class="token punctuation">(</span>d<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">              point<span class="token punctuation">.</span>p_offset <span class="token operator">=</span> cu<span class="token punctuation">;</span></span>
<span class="line">              point<span class="token punctuation">.</span>p_point <span class="token operator">+=</span> d<span class="token punctuation">;</span></span>
<span class="line">              <span class="token keyword">if</span> <span class="token punctuation">(</span>point<span class="token punctuation">.</span>p_offset <span class="token operator">==</span> cp<span class="token operator">-&gt;</span>c_used <span class="token operator">&amp;&amp;</span> cp<span class="token operator">-&gt;</span>c_next<span class="token punctuation">)</span></span>
<span class="line">                <span class="token punctuation">{</span></span>
<span class="line">                  cp <span class="token operator">=</span> cp<span class="token operator">-&gt;</span>c_next<span class="token punctuation">;</span></span>
<span class="line">                  point<span class="token punctuation">.</span>p_offset <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">                <span class="token punctuation">}</span></span>
<span class="line">              point<span class="token punctuation">.</span>p_chunk <span class="token operator">=</span> cp<span class="token punctuation">;</span></span>
<span class="line">              <span class="token keyword">break</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">          d <span class="token operator">-=</span> rest_cp<span class="token punctuation">;</span></span>
<span class="line">          point<span class="token punctuation">.</span>p_point <span class="token operator">+=</span> rest_cp<span class="token punctuation">;</span></span>
<span class="line">          point<span class="token punctuation">.</span>p_offset <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">          cp <span class="token operator">=</span> cp<span class="token operator">-&gt;</span>c_next<span class="token punctuation">;</span></span>
<span class="line">          <span class="token function">assert</span> <span class="token punctuation">(</span>cp<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token keyword">return</span> f<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>ようするに現在のチャンクの中のオフセットが何文字目かを見て、forwardの範囲が残りのチャンク内ならoffsetをずらすだけ、 そうでなければ目的のチャンクまで進んでそのチャンク内の目的の場所まで進む、とう感じか。</p><p>point自身はBufferは持って無くてWindowが持っているように見えるな。</p><p>新しくWindowを開く時に既存のpointをBufferから持ってくるのかと思っていたが、Windowから探すのか？まぁいい。</p><p>疑問なのはWindowのinvalidate的なのをやっている場所が無さそうな所。スクロールの位置なども何もしていないように見える。 つまりw_pointから毎回再計算しているという事か？</p><p>Window.hを眺めると、w_linenumとかw_columnとかを持っているので、これの更新の場所やこれを使った描画の場所を調べてみる。</p><p>disp.ccのpending_refreshがw_linenumとかの更新をしているっぽいな。 これはコマンドループで毎回呼ばれるっぽいので、Fforward_charなどを呼んだ後も毎回呼ばれると思って良さそうだ。</p><p>更新処理は抜粋して少し整理すると以下みたいになっている。</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>w_point<span class="token punctuation">.</span>p_point <span class="token operator">!=</span> w_last_point<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">      w_last_point <span class="token operator">=</span> w_point<span class="token punctuation">.</span>p_point<span class="token punctuation">;</span></span>
<span class="line">      <span class="token keyword">if</span> <span class="token punctuation">(</span>w_bufp<span class="token operator">-&gt;</span>b_fold_columns <span class="token operator">==</span> Buffer<span class="token double-colon punctuation">::</span>FOLD_NONE<span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">{</span></span>
<span class="line">          w_linenum <span class="token operator">=</span> w_bufp<span class="token operator">-&gt;</span><span class="token function">point_linenum</span> <span class="token punctuation">(</span>w_point<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">          w_column <span class="token operator">=</span> w_bufp<span class="token operator">-&gt;</span><span class="token function">point_column</span> <span class="token punctuation">(</span>w_point<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">      <span class="token keyword">else</span></span>
<span class="line">        w_linenum <span class="token operator">=</span> w_bufp<span class="token operator">-&gt;</span><span class="token function">folded_point_linenum_column</span> <span class="token punctuation">(</span>w_point<span class="token punctuation">,</span> <span class="token operator">&amp;</span>w_column<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>w_linenum <span class="token operator">&lt;</span> w_last_top_linenum<span class="token punctuation">)</span></span>
<span class="line">    w_last_top_linenum <span class="token operator">=</span> w_linenum<span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>w_linenum <span class="token operator">&gt;=</span> w_last_top_linenum <span class="token operator">+</span> w_ech<span class="token punctuation">.</span>cy<span class="token punctuation">)</span></span>
<span class="line">    w_last_top_linenum <span class="token operator">=</span> w_linenum <span class="token operator">-</span> w_ech<span class="token punctuation">.</span>cy <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>w_disp_flags <span class="token operator">&amp;</span> WDF_GOAL_COLUMN<span class="token punctuation">)</span></span>
<span class="line">    w_goal_column <span class="token operator">=</span> w_column<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>更新するだけでpaint系の処理はされていないな。paintのフラグは結構複雑だが、この辺は最適化の話なので適当に描かれると思っておこう。 基本的には以下で更新される。</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line">          w_linenum <span class="token operator">=</span> w_bufp<span class="token operator">-&gt;</span><span class="token function">point_linenum</span> <span class="token punctuation">(</span>w_point<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">          w_column <span class="token operator">=</span> w_bufp<span class="token operator">-&gt;</span><span class="token function">point_column</span> <span class="token punctuation">(</span>w_point<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>つまりWindowのw_pointを更新しておくと、イベントループで非同期にw_linenumとw_columnを更新する訳だな。</p><p>point_linenumはmove.ccにある。</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token keyword">long</span></span>
<span class="line"><span class="token class-name">Buffer</span><span class="token double-colon punctuation">::</span><span class="token function">point_linenum</span> <span class="token punctuation">(</span>point_t goal<span class="token punctuation">)</span> <span class="token keyword">const</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">long</span> linenum <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line">  point_t point <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">const</span> Chunk <span class="token operator">*</span>cp<span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">for</span> <span class="token punctuation">(</span>cp <span class="token operator">=</span> b_chunkb<span class="token punctuation">;</span> point <span class="token operator">+</span> cp<span class="token operator">-&gt;</span>c_nchars <span class="token operator">&lt;</span> goal<span class="token punctuation">;</span> cp <span class="token operator">=</span> cp<span class="token operator">-&gt;</span>c_next<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">      <span class="token keyword">if</span> <span class="token punctuation">(</span>cp<span class="token operator">-&gt;</span>c_nlines <span class="token operator">==</span> <span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">(</span><span class="token punctuation">(</span>Chunk <span class="token operator">*</span><span class="token punctuation">)</span>cp<span class="token punctuation">)</span><span class="token operator">-&gt;</span>c_nlines <span class="token operator">=</span> cp<span class="token operator">-&gt;</span><span class="token function">count_lines</span> <span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">      linenum <span class="token operator">+=</span> cp<span class="token operator">-&gt;</span>c_nlines<span class="token punctuation">;</span></span>
<span class="line">      point <span class="token operator">+=</span> cp<span class="token operator">-&gt;</span>c_nchars<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token keyword">int</span> remaining_cp <span class="token operator">=</span> <span class="token keyword">int</span> <span class="token punctuation">(</span>goal <span class="token operator">-</span> point<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">int</span> cu_end <span class="token operator">=</span> <span class="token function">chunk_forward_cp</span> <span class="token punctuation">(</span>cp<span class="token operator">-&gt;</span>c_text<span class="token punctuation">,</span> cp<span class="token operator">-&gt;</span>c_used<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> remaining_cp<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">const</span> Char <span class="token operator">*</span>p <span class="token operator">=</span> cp<span class="token operator">-&gt;</span>c_text<span class="token punctuation">,</span> <span class="token operator">*</span>pe <span class="token operator">=</span> p <span class="token operator">+</span> cu_end<span class="token punctuation">;</span> p <span class="token operator">&lt;</span> pe<span class="token punctuation">;</span> p<span class="token operator">++</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">*</span>p <span class="token operator">==</span> <span class="token char">&#39;\\n&#39;</span><span class="token punctuation">)</span></span>
<span class="line">      linenum<span class="token operator">++</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> linenum<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>チャンクを先頭からなめているが、cpごとの行数はキャッシュされるんだろうな…とコードを見たらされてないな。毎回全文字を数えるのか。 そのくらいは大した問題では無いって事かね。</p><p>pending_refreshに戻って、w_last_top_linenumの更新を見てみる。</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>w_linenum <span class="token operator">&lt;</span> w_last_top_linenum<span class="token punctuation">)</span></span>
<span class="line">    w_last_top_linenum <span class="token operator">=</span> w_linenum<span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>w_linenum <span class="token operator">&gt;=</span> w_last_top_linenum <span class="token operator">+</span> w_ech<span class="token punctuation">.</span>cy<span class="token punctuation">)</span></span>
<span class="line">    w_last_top_linenum <span class="token operator">=</span> w_linenum <span class="token operator">-</span> w_ech<span class="token punctuation">.</span>cy <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>次のlinenumが以下の場合は更新。</p><ul><li>前回表示した一番上より小さい場合</li><li>前回表示したlinenum+w_ech.cy+1</li></ul><p>w_echはWindowの行数と思えばいいかな。 でもw_last_top_linenumを更新しても表示のフラグを何も立てていないな。まぁそこはどうにかしているんだろう。</p><p>これだとスクロールしていく時には一行ずつしか進まないし一番端まで行かないと動かない気がするな。まぁその辺はC-nの挙動とC-vで違えばそんなには気にならないか。</p><p>とりあえずlinenumはいいとして、columnの方は何もしてないな。 w_top_columnの更新はどうしているのだろう？</p><p>disp.ccのWindow::reframeがそれっぽいな。 これはかなり複雑だが、関係ありそうな所を抜き出すと以下みたいな感じか。</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line">  column <span class="token operator">=</span> w_bufp<span class="token operator">-&gt;</span><span class="token function">point_column</span> <span class="token punctuation">(</span>w_point<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  w_column <span class="token operator">=</span> column<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>column <span class="token operator">&lt;</span> w_top_column<span class="token punctuation">)</span></span>
<span class="line">    w_top_column <span class="token operator">=</span> column <span class="token operator">/</span> hjump <span class="token operator">*</span> hjump<span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>column <span class="token operator">&gt;=</span> w_top_column <span class="token operator">+</span> maxwidth<span class="token punctuation">)</span></span>
<span class="line">    w_top_column <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">(</span>column <span class="token operator">-</span> maxwidth <span class="token operator">+</span> hjump<span class="token punctuation">)</span> <span class="token operator">/</span> hjump <span class="token operator">*</span> hjump<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>column <span class="token operator">&lt;</span> w_top_column <span class="token operator">||</span> column <span class="token operator">-</span> w_top_column <span class="token operator">&gt;=</span> maxwidth<span class="token punctuation">)</span></span>
<span class="line">    w_top_column <span class="token operator">=</span> column<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>hjunmpはw_hjump_columnsから来ていて、デフォルトは8。8列くらい余裕がある感じに設定するイメージか。</p><p>左端なら左端、右端なら画面端ぶんくらい引いた場所に設定している。</p><p>ようするに</p><ol><li>Windowがpointを持つ</li><li>pointからcolumnとlinenumを計算し、前回のtop_columnとtop_linenumと比較して画面内なら動かさない、画面外なら再計算した値を基準に適当に設定してpaint</li></ol><p>という感じか。</p><h2 id="lemの作者に質問" tabindex="-1"><a class="header-anchor" href="#lemの作者に質問"><span>lemの作者に質問</span></a></h2><ul><li>self-insertとかinsertをどうやって追ったらいいか？ <ul><li>define-command, insertはinsert-characterでdefunでわかる（basic.lisp）</li></ul></li><li>self-insert時のキーボード入力の変数 <ul><li>key-sequenceとかinput.lispにlast-read-key-sequence</li></ul></li><li>DeleteとかBackspaceとかTabとかReturnの名前など <ul><li>key.lispのnamed-key-syms</li></ul></li><li>再描画の話</li><li>Bufferの無いWindowはある？ <ul><li>無い。</li></ul></li><li>skk-modeとかvi-modeどうやって作ったか？</li><li>C-x C-s とかの複数キーのキーマップの内部実装 <ul><li>keymap.lispにあるとか。ハッシュか関数が入っていて、ハッシュだったら〜的に動く。ハッシュだったら一旦保存して次を促し、全部揃ったら送られる感じ。</li></ul></li><li>switch-bufferする時のpointはどこからとってる？ <ul><li>bufferにも保存している</li><li>swtich-to-bufferでインターナルは%で始まる方</li></ul></li><li>バッファが変更されてる時のwindowの振る舞い <ul><li>そもそもpointはbuffer側が全部持っている</li></ul></li><li>マーカーはバッファが持つ</li></ul>`,174)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};